window.SCHOOL_LISTENING={"../assets/media/85aacc1a165933d0de800c88c681674161621dcc6fc27bdf9a253966f7692831.mp3":[{"id":"PPT_85aacc1a165933d0","audioId":"PPT_85aacc1a165933d0","title":"Book 2 · Unit 1 · RW · READING 1","subtitle":"READING 1 · source slide 46","duration":191.95,"cues":[{"start":0,"end":2.08,"text":"Rise of the Mega Cities","coverage":1},{"start":2.86,"end":4,"text":"Mega City,","coverage":1},{"start":4.42,"end":7.42,"text":"a city with more than ten million people.","coverage":1},{"start":8.32,"end":11.72,"text":"The number of Mega Cities is growing very quickly.","coverage":1},{"start":12.5,"end":17.04,"text":"In the 1950s, there were only two Mega Cities in the world.","coverage":1},{"start":17.52,"end":18.04,"text":"Today,","coverage":1},{"start":18.52,"end":23.54,"text":"12 % of the world's urban population lives in Mega Cities.","coverage":1},{"start":24.18,"end":27.46,"text":"Studies show that there will be eight .five","coverage":1},{"start":27.46,"end":30.5,"text":"billion people in the world in 2030.","coverage":1},{"start":31.54,"end":34.66,"text":"Experts say that there will be 40 Mega Cities.","coverage":1},{"start":35.92,"end":40.72,"text":"Today, more than 35 cities in the world are Mega Cities.","coverage":1},{"start":41.38,"end":43.3,"text":"The majority are in Asia,","coverage":1},{"start":43.8,"end":45.76,"text":"South America and Africa.","coverage":1},{"start":46.64,"end":53.64,"text":"More and more people around the world are leaving their homes in the countryside and moving to the city.","coverage":1},{"start":54.82,"end":57.64,"text":"Many Mega Cities have better opportunities,","coverage":1},{"start":58.12,"end":62.16,"text":"such as more jobs and a choice of schools and universities.","coverage":1},{"start":63.14,"end":66.58,"text":"Mega Cities are also exciting places to live.","coverage":1},{"start":67,"end":69.14,"text":"There are lots of different people,","coverage":1},{"start":69.62,"end":71.12,"text":"languages and restaurants,","coverage":1},{"start":71.52,"end":74.64,"text":"and there are many interesting things to do.","coverage":1},{"start":75.68,"end":76.3,"text":"However,","coverage":1},{"start":76.84,"end":78.44,"text":"Mega Cities have problems,","coverage":1},{"start":78.88,"end":78.96,"text":"too.","coverage":1},{"start":79.54,"end":85.86,"text":"The cities are very big, and this can cause problems like pollution or poor housing.","coverage":1},{"start":87.88,"end":88.66,"text":"Tokyo, Japan,","coverage":1},{"start":89.24,"end":90.76,"text":"37 .four","coverage":1},{"start":90.76,"end":91.4,"text":"million.","coverage":1},{"start":92.38,"end":96.2,"text":"Tokyo is an exciting modern city in the east of Japan.","coverage":1},{"start":96.74,"end":101.94,"text":"There are lots of jobs because most big companies in Japan are in Tokyo.","coverage":1},{"start":102.84,"end":105.76,"text":"It is also an excellent place to study.","coverage":1},{"start":105.76,"end":110.46,"text":"18 % of Japan's universities are in the city.","coverage":1},{"start":111.26,"end":111.78,"text":"However,","coverage":1},{"start":112.32,"end":116.52,"text":"Tokyo is very busy and the traffic is very bad.","coverage":1},{"start":117.22,"end":119.24,"text":"More than seven .five","coverage":1},{"start":119.24,"end":123,"text":"million people use the Tokyo Metro every day.","coverage":1},{"start":125.24,"end":126.14,"text":"Delhi, India,","coverage":1},{"start":126.9,"end":128.28,"text":"29 .four","coverage":1},{"start":128.28,"end":128.82,"text":"million.","coverage":1},{"start":129.82,"end":132.46,"text":"Delhi is in the north of India.","coverage":1},{"start":132.96,"end":135.58,"text":"It has many beautiful monuments,","coverage":1},{"start":136.06,"end":139.24,"text":"interesting museums and modern restaurants.","coverage":1},{"start":140.42,"end":144.1,"text":"There is an exciting mix of different cultures in the city,","coverage":1},{"start":144.52,"end":147.08,"text":"and there are four official languages,","coverage":1},{"start":147.76,"end":148.3,"text":"Hindi,","coverage":1},{"start":148.92,"end":149.4,"text":"Urdu,","coverage":1},{"start":149.88,"end":151.98,"text":"Punjabi and English.","coverage":1},{"start":152.9,"end":157.16,"text":"However, there are not enough houses in some parts of Delhi.","coverage":1},{"start":157.86,"end":162.44,"text":"This means that many people live in large slums in the city.","coverage":1},{"start":164.2,"end":165.6,"text":"Cairo, Egypt,","coverage":1},{"start":166.44,"end":167.52,"text":"20 .five","coverage":1},{"start":167.52,"end":168.24,"text":"million.","coverage":1},{"start":169.2,"end":174.74,"text":"Cairo is the capital of Egypt and is the second largest city in Africa.","coverage":1},{"start":175.72,"end":178.78,"text":"Cairo has important car and film industries.","coverage":1},{"start":179.7,"end":184.74,"text":"The city is the center of many government offices and has many universities,","coverage":1},{"start":185.74,"end":190.1,"text":"one of which is over one ,200 years old.","coverage":1}],"file":"0e5581564b0cfa040307.js","track":0,"media":"../assets/media/85aacc1a165933d0de800c88c681674161621dcc6fc27bdf9a253966f7692831.mp3"}],"../assets/media/733412a4e1bac5e430136f74bf1cf57e9bfce39ed9af39b6666cada848567f0e.mp3":[{"id":"PPT_733412a4e1bac5e4","audioId":"PPT_733412a4e1bac5e4","title":"Book 2 · Unit 1 · RW · READING 2","subtitle":"READING 2 · source slide 81","duration":182.52,"cues":[{"start":0,"end":1.86,"text":"Home stay holidays,","coverage":1},{"start":2.3,"end":4.28,"text":"a home away from home.","coverage":1},{"start":5.2,"end":7.26,"text":"Places to stay.","coverage":1},{"start":8.12,"end":8.9,"text":"Location.","coverage":1},{"start":9.32,"end":10.32,"text":"Check -in.","coverage":1},{"start":10.72,"end":11.42,"text":"Checkout.","coverage":1},{"start":12.52,"end":13.3,"text":"Guests.","coverage":1},{"start":14.02,"end":16.92,"text":"Home stays are becoming more and more popular,","coverage":1},{"start":17.56,"end":22.22,"text":"and people around the world are offering their homes as places to stay.","coverage":1},{"start":23.32,"end":30.12,"text":"Home stays offer cheap places to stay and the chance for guests to see the area like local people.","coverage":1},{"start":30.92,"end":36.1,"text":"They're very popular with students who want to stay in another country and learn a language.","coverage":1},{"start":37.06,"end":42.04,"text":"We asked three families who run home stays to tell us about where they live.","coverage":1},{"start":44.26,"end":45.64,"text":"Stay in the mountains.","coverage":1},{"start":46.56,"end":47.68,"text":"The Atal family.","coverage":1},{"start":48.76,"end":55.78,"text":"Our family home is in the north of Nepal, in the Himalayan mountains, in the village of Manang.","coverage":1},{"start":56.52,"end":59.38,"text":"The village is small and very quiet.","coverage":1},{"start":59.82,"end":61.92,"text":"It is a very friendly place.","coverage":1},{"start":62.72,"end":65.22,"text":"The mountains are extremely beautiful.","coverage":1},{"start":65.9,"end":70.88,"text":"You can go for long walks and swim in the rivers, but there are","coverage":1},{"start":70.88,"end":71.28,"text":"no","coverage":1},{"start":71.28,"end":71.82,"text":"shops,","coverage":1},{"start":72.3,"end":73.84,"text":"cinemas or cafes.","coverage":1},{"start":75.22,"end":77.64,"text":"A house by the sea.","coverage":1},{"start":78.24,"end":79.94,"text":"Kate and Julian Foxton.","coverage":1},{"start":81.2,"end":86.02,"text":"Our two -bedroom house is by the sea in the southwest of England.","coverage":1},{"start":86.6,"end":91.48,"text":"It is 15 minutes drive to the nearest village of Port Reith.","coverage":1},{"start":92.28,"end":97.74,"text":"There are lots of beaches, rivers and forests and it is very quiet.","coverage":1},{"start":98.22,"end":104.28,"text":"We spend a lot of time reading books, watching films and going for walks.","coverage":1},{"start":104.94,"end":108.64,"text":"Our area is great for sports like surfing,","coverage":1},{"start":109,"end":110.88,"text":"kayaking and mountain biking.","coverage":1},{"start":111.52,"end":112.12,"text":"However,","coverage":1},{"start":112.48,"end":115,"text":"the houses here are expensive,","coverage":1},{"start":115.32,"end":118.26,"text":"which can be a problem for local people.","coverage":1},{"start":118.78,"end":119.36,"text":"There are","coverage":1},{"start":119.36,"end":119.82,"text":"no","coverage":1},{"start":119.82,"end":126.14,"text":"buses or trains here, so it can be difficult to get around without a car.","coverage":1},{"start":128.02,"end":129.62,"text":"City Holiday.","coverage":1},{"start":130.28,"end":132.18,"text":"Shafik and Asma Halwani.","coverage":1},{"start":133.26,"end":138.52,"text":"Our home is near the historic city center of Beirut, Lebanon,","coverage":1},{"start":139.14,"end":141.28,"text":"a large city in the Middle East.","coverage":1},{"start":141.98,"end":144.64,"text":"There are lots of cafes and restaurants,","coverage":1},{"start":145.04,"end":146.92,"text":"which are open late at night.","coverage":1},{"start":147.56,"end":153.78,"text":"We love it here because it's so friendly and you can always find what you need.","coverage":1},{"start":154.56,"end":158.32,"text":"Lots of people come here to learn Arabic and French.","coverage":1},{"start":159.2,"end":162.76,"text":"There are also a lot of jobs and businesses here.","coverage":1},{"start":163.5,"end":164.06,"text":"However,","coverage":1},{"start":164.44,"end":170.3,"text":"it can be noisy at night and there is a lot of traffic during the day.","coverage":1},{"start":171.14,"end":173.94,"text":"The best thing about Beirut is the weather.","coverage":1},{"start":174.5,"end":176.66,"text":"It is nice all year round.","coverage":1},{"start":177.2,"end":178.62,"text":"It rains in the winter,","coverage":1},{"start":179.04,"end":179.82,"text":"but there is","coverage":1},{"start":179.82,"end":180.12,"text":"no","coverage":1},{"start":180.12,"end":180.58,"text":"snow.","coverage":1}],"file":"bea913810b2ee7f065ec.js","track":0,"media":"../assets/media/733412a4e1bac5e430136f74bf1cf57e9bfce39ed9af39b6666cada848567f0e.mp3"}]};
window.SCHOOL_SOURCE_ANSWERS=[{"text":"1  Ships are safe from the storm in the harbour.","slide":10,"shape":"8","bookPage":"16"},{"text":"2  The final destination on our trip is a small island.","slide":10,"shape":"9","bookPage":"16"},{"text":"3  This monument helps people remember an important event.","slide":10,"shape":"10","bookPage":"16"},{"text":"4  We saw bright fireworks in the sky during the celebration.","slide":12,"shape":"8","bookPage":"16"},{"text":"5  The tower is the tallest part of the building.","slide":12,"shape":"9","bookPage":"16"},{"text":"6  The ships carry goods that shops can sell.","slide":12,"shape":"10","bookPage":"16"},{"text":"What is the capital city of your country? Is it a popular destination for tourists? Why / Why not?Possible answer: Beijing is the capital of China. It attracts tourists with its historic places.","slide":14,"shape":"18","bookPage":"16"},{"text":"Do you know what a megacity is? What do you think the three biggest megacities in the world are?Possible answer: A megacity is a very large city. My guesses are Tokyo, Delhi and Shanghai.","slide":14,"shape":"20","bookPage":"16"},{"text":"Which big cities in your country have a harbour? Why are harbours important to cities?Possible answer: Shanghai has a harbour. Ships bring goods for people to buy and sell.","slide":15,"shape":"18","bookPage":"16"},{"text":"Look at the photos. Which predictions does the video confirm?Asia; a megacity, popular destination and capital city; an old town and a harbour.","slide":23,"shape":"7","bookPage":"16"},{"text":"How many people live in Jakarta?a 9 million b 11 millionCorrect answer: a 9 million.","slide":23,"shape":"21","bookPage":"16"},{"text":"What style of buildings can you see in the old town?a Indonesian b EuropeanCorrect answer: b European.","slide":23,"shape":"23","bookPage":"16"},{"text":"What can you see at Sunda Kelapa harbour?a ships from Europe, China and India b Indonesian shipsCorrect answer: b Indonesian ships.","slide":24,"shape":"6","bookPage":"16"},{"text":"What is under the national monument?a a golden flame b the National MuseumCorrect answer: b the National Museum.","slide":24,"shape":"20","bookPage":"16"},{"text":"What is soto?a meat and vegetable soup b a fried rice dishCorrect answer: a meat and vegetable soup.","slide":24,"shape":"22","bookPage":"16"},{"text":"Why does Jakarta have very busy roads?Possible answer: Two million people travel into Jakarta to work each day.","slide":25,"shape":"20","bookPage":"16"},{"text":"Why did Jakarta grow into a big city?Possible answer: Its harbour supported international trade.","slide":25,"shape":"21","bookPage":"16"},{"text":"Why are there European-style buildings in Jakarta?Possible answer: Dutch traders built the European-style buildings.","slide":25,"shape":"22","bookPage":"16"},{"text":"How long have people lived in Indonesia?Possible answer: Probably 1.5 million years.","slide":26,"shape":"14","bookPage":"16"},{"text":"Who is the video for – tourists or business people? Why?Possible answer: Tourists: it introduces attractions, food and a celebration.","slide":26,"shape":"15","bookPage":"16"},{"text":"Compare Jakarta to another city you know well. How is it similar or different?Possible answer: Jakarta and London are both large cities, but their building styles differ.","slide":28,"shape":"18","bookPage":"17"},{"text":"Imagine you are making a video about your capital city for tourists. What information and places would you include?Possible answer: I would show historic buildings, local food and places to visit.","slide":28,"shape":"19","bookPage":"17"},{"text":"What different information would you include in a video for business people?Possible answer: I would include transport, business areas and places to stay.","slide":28,"shape":"20","bookPage":"17"},{"text":"1  In some modern cities there is a lot of pollution from cars and factory smoke. This is\na big problem for the world today.","slide":39,"shape":"7","bookPage":"18"},{"text":"2  Living in the countryside is boring. It is better to live in a city or town.","slide":39,"shape":"8","bookPage":"18"},{"text":"3  A city is planning a new road. The city does not need to ask an expert to help them\nplan the new road.","slide":39,"shape":"9","bookPage":"18"},{"text":"Look at the information in the infographic. Tell a partner what you think the article is about.Possible answer: The article is probably about the growth of megacities.","slide":41,"shape":"13","bookPage":"18"},{"text":"1  Our city needs more housing for its growing population.","slide":45,"shape":"8","bookPage":"19"},{"text":"2  The new park gives people in this urban area a quiet place to relax.","slide":45,"shape":"9","bookPage":"19"},{"text":"5  number of people who use the Tokyo Metro = 7.5 million","slide":56,"shape":"6","bookPage":"21"},{"text":"6  percentage of Japanese universities in Tokyo = 18 %","slide":56,"shape":"7","bookPage":"21"},{"text":"7  number of people living in Delhi = 29.4 million","slide":56,"shape":"8","bookPage":"21"},{"text":"8  number of official languages spoken in Delhi = four","slide":56,"shape":"9","bookPage":"21"},{"text":"Most megacities are in Europe.False. Most are in Asia, South America and Africa.","slide":57,"shape":"19","bookPage":"20"},{"text":"Finding a nice place to live is easy in megacities.False. Finding a nice place to live can be difficult.","slide":57,"shape":"20","bookPage":"20"},{"text":"1 number of megacities in 1950 = two","slide":57,"shape":"21","bookPage":"20"},{"text":"2 predicted number of megacities in 2030 = 40","slide":57,"shape":"22","bookPage":"20"},{"text":"3 percentage of urban population in the world that lives in megacities = 12 %","slide":57,"shape":"6","bookPage":"20"},{"text":"4 expected global population in 2030 = 8.5 billion","slide":57,"shape":"7","bookPage":"20"},{"text":"Tokyo\nlots of jobs; bad traffic; busy trains; good place to study\nDelhi\ninteresting places to visit; mix of different people; housing problem\nCairo\nimportant industries; good place to study","slide":58,"shape":"16","bookPage":"20"},{"text":"Look at the word slums underlined in the article. What do you think it means?a a very poor and crowded area in a cityb a very unclean housec a very expensive area in the centre of a cityCorrect answer: a a very poor and crowded area in a city","slide":62,"shape":"11","bookPage":"21"},{"text":"1. Before choosing a plan, Riverton's leaders asked residents about the town centre. To find out how busy the area was, they also counted people at different times of day.","slide":65,"shape":"5","bookPage":null},{"text":"4. Older residents asked for benches to sit on, while parents asked for safe crossings after school.","slide":65,"shape":"8","bookPage":null},{"text":"11. Headings: i. Surveying everyday problems before a plan; ii. Building a new centre outside town; iii. Removing every vehicle; iv. Changing street access and parking; v. Combining different groups' needs; vi. Benefits beyond visitor numbers; vii. Managing costs after popularity.\nParagraph A: i. Surveying everyday problems before a plan","slide":66,"shape":"5","bookPage":null},{"text":"14. Paragraph D: vi. Benefits beyond visitor numbers","slide":66,"shape":"8","bookPage":null},{"text":"21. What does the writer acknowledge about the new route?\nA. It prevents all deliveries.\nB. It is not shorter for everyone.\nC. It removes all bus stops.","slide":67,"shape":"5","bookPage":null},{"text":"23. How does the council assess success?\nA. It measures only shop rents.\nB. It counts only new buildings.\nC. It considers safety and comfort as well as visitors.","slide":67,"shape":"8","bookPage":null},{"text":"5  In Manchester, we took the bus to the city centre. That is where the main tourist sites\nin the city are located.","slide":79,"shape":"7","bookPage":"22"},{"text":"6  It’s getting more expensive to live in big cities, so people who can’t pay the high prices\nare moving away.","slide":79,"shape":"8","bookPage":"22"},{"text":"7  There was a lot of traffic on my street last night. It was too loud to sleep because of all\nthe noisy cars.","slide":79,"shape":"9","bookPage":"22"},{"text":"What do you think a homestay holiday is?Possible answer: A holiday where you stay in local people’s homes instead of a hotel.","slide":82,"shape":"17","bookPage":"22"},{"text":"Who offers homestays?Possible answer: People around the world offer homestays.","slide":82,"shape":"18","bookPage":"22"},{"text":"Are homestays expensive?Possible answer: No. They offer cheap places to stay.","slide":82,"shape":"19","bookPage":"22"},{"text":"What do homestays give guests the chance to do?Possible answer: Guests can see the area like local people.","slide":82,"shape":"20","bookPage":"22"},{"text":"Who are homestays popular with and why?Possible answer: Students who want to stay in another country and learn a language.","slide":83,"shape":"14","bookPage":"22"},{"text":"1 Which place would be great for somebody who wants to practise English?B — the Foxtons’ home in England.","slide":91,"shape":"19","bookPage":"24"},{"text":"2 Which place would be good for business travel?C — the Halwany home in Beirut.","slide":91,"shape":"20","bookPage":"24"},{"text":"3 Which places are good for people who like long walks and nature?A and B — the Atal and Foxton homes.","slide":91,"shape":"21","bookPage":"24"},{"text":"4 Which place would be good for somebody who enjoys city life?C — the Halwany home in Beirut.","slide":91,"shape":"22","bookPage":"24"},{"text":"5 Which place would be good for somebody who doesn’t have a car?C — the Halwany home in central Beirut.","slide":92,"shape":"20","bookPage":"24"},{"text":"6 Which place would be good for somebody who loves sport?B — the Foxton home, with surfing, kayaking and mountain biking.","slide":92,"shape":"21","bookPage":"24"},{"text":"1  What is the name of the family?\nThe Atal family\n2  Where is the homestay?\nManang, a small village in northern Nepal\n3  What kind of places are there near the homestay? (e.g., beaches, cinemas, etc.)\nMountains and rivers; no shops, cinemas or cafés\n4  What can visitors do in the area?\nLong walks and swimming","slide":93,"shape":"14","bookPage":"24"},{"text":"1  What is the name of the family?\nKate and Julian Foxton\n2  Where is the homestay?\nSouth-west England, near Portreath\n3  What kind of places are there near the homestay? (e.g., beaches, cinemas, etc.)\nBeaches, rivers and forests\n4  What can visitors do in the area?\nSurfing, kayaking, mountain biking, reading, watching films and walking","slide":94,"shape":"14","bookPage":"24"},{"text":"1  What is the name of the family?\nChafic and Asma Halwany\n2  Where is the homestay?\nNear the historic city centre of Beirut, Lebanon\n3  What kind of places are there near the homestay? (e.g., beaches, cinemas, etc.)\nCafés and restaurants\n4  What can visitors do in the area?\nLearn Arabic and French; enjoy city life","slide":95,"shape":"14","bookPage":"24"},{"text":"Identify the nouns: Tokyo is an exciting, modern city in the east of Japan.","slide":98,"shape":"12","bookPage":"25"},{"text":"Identify the adjectives: Tokyo is an exciting, modern city in the east of Japan.","slide":98,"shape":"13","bookPage":"25"},{"text":"A: ugly, quiet, polluted, boringB: beautiful, expensive, quiet, boring, cleanC: beautiful, expensive, ugly, cheap, noisy, polluted, interesting","slide":102,"shape":"12","bookPage":"25"},{"text":"positive (+)\nnegative (–)\n(+) or (–)\nbeautiful\nboring; noisy\ncheap; expensive\nclean; interesting\npolluted; ugly\nquiet","slide":103,"shape":"15","bookPage":"25"},{"text":"food: countable or uncountable?Correct answer: U","slide":106,"shape":"11","bookPage":"26"},{"text":"building: countable or uncountable?Correct answer: C","slide":106,"shape":"12","bookPage":"26"},{"text":"water: countable or uncountable?Correct answer: U","slide":106,"shape":"13","bookPage":"26"},{"text":"park: countable or uncountable?Correct answer: C","slide":106,"shape":"14","bookPage":"26"},{"text":"Find two countable nouns in Text C.Possible answer: cafés; restaurants","slide":109,"shape":"15","bookPage":"26"},{"text":"Find two uncountable nouns in Text C.Possible answer: traffic; weather","slide":109,"shape":"16","bookPage":"26"},{"text":"1  They brought X bicycles to go to the mountains.","slide":112,"shape":"6","bookPage":"26"},{"text":"2  In a cinema, there is usually a sign for the exit.","slide":112,"shape":"7","bookPage":"26"},{"text":"3  I love to try different kinds of X food when I visit new cities.","slide":112,"shape":"8","bookPage":"26"},{"text":"4  You can easily take a train from Paris to Brussels.","slide":112,"shape":"9","bookPage":"26"},{"text":"5  I check my email in an internet café.","slide":112,"shape":"10","bookPage":"26"},{"text":"6  I usually travel with a friend.","slide":112,"shape":"11","bookPage":"26"},{"text":"7  Large cities often have X air pollution.","slide":112,"shape":"12","bookPage":"26"},{"text":"HiTokyo is great. There are (1) lots of cafés and other places to eat. As you know, my town is small and only has (2) a few restaurants. (3) Many people live here and there is (4) a lot of public transport. Go online if you want to find (5) some things to do in the city when you visit me in the summer. Send me an email and tell me (6) a little information about your town or city.","slide":116,"shape":"18","bookPage":"27"},{"text":"Write a short email to Karina with three things about your town or city.Possible answer: Hi Karina, My city has a lot of traffic at night. We have many friendly people. I have a few helpful neighbours.","slide":118,"shape":"12","bookPage":"27"},{"text":"The town is quiet.","slide":122,"shape":"6","bookPage":null},{"text":"My town has many shops.","slide":122,"shape":"10","bookPage":null},{"text":"I live in a modern apartment. My apartment has a big window. That window faces a park.","slide":123,"shape":"6","bookPage":null},{"text":"The village has a few small houses. They stand near green fields and hills.","slide":124,"shape":"7","bookPage":null},{"text":"1. The survey was completed in January. NOT GIVEN","slide":131,"shape":"5","bookPage":null},{"text":"3. The survey cost more than a new building. FALSE","slide":131,"shape":"8","bookPage":null},{"text":"18. A regular yearly opportunity for residents to give their views. E","slide":132,"shape":"5","bookPage":null},{"text":"20. A reduction in both traffic noise and minor road accidents. D","slide":132,"shape":"8","bookPage":null},{"text":"21. Which TWO reasons explain why leaders began with a survey?\nA. To prove every resident wanted a new building.\nB. To choose shops with the highest sales.\nC. To count only people arriving by bus.\nD. To understand difficulties before choosing a plan.\nE. To find out how residents used the area.","slide":133,"shape":"5","bookPage":null},{"text":"3. Lina arranged to use a ferry with spare room on Tuesday.","slide":136,"shape":"5","bookPage":null},{"text":"7. She replaced the cardboard boxes with strong containers that had lids.","slide":136,"shape":"8","bookPage":null},{"text":"11. Headings: i. Protecting books on the final part of the journey; ii. Sharing responsibility among villages; iii. Responding to different reading interests; iv. Keeping the service available through winter; v. Using an existing journey to deliver books; vi. Charging readers for cancelled sailings; vii. Replacing village schools with one library.\nParagraph A: v. Using an existing journey to deliver books","slide":137,"shape":"5","bookPage":null},{"text":"13. Paragraph C: i. Protecting books on the final part of the journey","slide":137,"shape":"8","bookPage":null},{"text":"16. Why was the existing ferry chosen?\nA. It travelled only for the library.\nB. It could reach the town faster than every bus.\nC. It had spare space and avoided the cost of a special boat.","slide":138,"shape":"5","bookPage":null},{"text":"18. Why were local helpers appointed?\nA. To let readers collect books within their own villages.\nB. To make every reader travel to one central collection point.\nC. To choose a new ferry company.","slide":139,"shape":"5","bookPage":null},{"text":"Our village has a few local shops.","slide":146,"shape":"6","bookPage":null},{"text":"This area does not have much traffic.","slide":146,"shape":"10","bookPage":null},{"text":"The road outside my home has a lot of traffic. The traffic makes the road noisy. Because of that noise, I keep my window closed.","slide":147,"shape":"6","bookPage":null},{"text":"Our guesthouse is near the sea. It has a courtyard outside. We can sit there and enjoy the view.","slide":148,"shape":"7","bookPage":null},{"text":"What is the main difference between the places described in Reading 1 and Reading 2?Possible answer: Reading 1 discusses advantages and disadvantages of megacities. Reading 2 describes homestay holidays in the countryside and a city.","slide":150,"shape":"11","bookPage":"28"},{"text":"lots of cafés and restaurants: positive or negative?Correct answer: +","slide":154,"shape":"17","bookPage":"28"},{"text":"places stay open late at night: positive or negative?Correct answer: +","slide":154,"shape":"18","bookPage":"28"},{"text":"a lot of traffic: positive or negative?Correct answer: –","slide":154,"shape":"19","bookPage":"28"},{"text":"it can be noisy: positive or negative?Correct answer: –","slide":154,"shape":"20","bookPage":"28"},{"text":"a lot of jobs and businesses: positive or negative?Correct answer: +","slide":155,"shape":"18","bookPage":"28"},{"text":"positive (+)\nnegative (–)\nLots of cafés and restaurants\nA lot of traffic\nPlaces stay open late at night\nIt can be noisy\nA lot of jobs and businesses\n","slide":156,"shape":"14","bookPage":"28"},{"text":"Share your T-chart with a group. Do you agree or disagree with each other? Explain your opinion.Possible answer: I think a quiet village is positive because I can relax. My partner prefers a busy place with more activities.","slide":164,"shape":"19","bookPage":"29"},{"text":"positive (+)\nnegative (–)\nGood public transport\nHigh costs\nMuseums\nFew green spaces","slide":165,"shape":"14","bookPage":"29"},{"text":"positive (+)\nnegative (–)\nbeautiful\nnot many buses or trains\nFriendly, quiet village\nNo shops or cafés","slide":166,"shape":"14","bookPage":"29"},{"text":"positive (+)\nnegative (–)\nA modern transport system; friendly neighbours\nExpensive houses; heavy traffic\nInteresting places\nCrowded shops","slide":168,"shape":"17","bookPage":"29"},{"text":"1 Paris is a beautiful city.Subject: Paris; verb: is.","slide":172,"shape":"14","bookPage":"30"},{"text":"2 The town does not have a park.Subject: The town; verb: does not have.","slide":172,"shape":"15","bookPage":"30"},{"text":"3 I live in a small town.Subject: I; verb: live.","slide":172,"shape":"16","bookPage":"30"},{"text":"4 Istanbul has many attractions.Subject: Istanbul; verb: has.","slide":172,"shape":"17","bookPage":"30"},{"text":"The countryside is not very exciting. Is the sentence correct?Correct answer: ✓","slide":174,"shape":"17","bookPage":"30"},{"text":"Studies business at university in Dubai. Is the sentence correct?Correct answer: ✗ — She studies business at university in Dubai.","slide":174,"shape":"18","bookPage":"30"},{"text":"My lives in a busy and modern city. Is the sentence correct?Correct answer: ✗ — My friend lives in a busy and modern city.","slide":174,"shape":"19","bookPage":"30"},{"text":"The houses here are very expensive. Is the sentence correct?Correct answer: ✓","slide":174,"shape":"20","bookPage":"30"},{"text":"The village very quiet. Is the sentence correct?Correct answer: ✗ — The village is very quiet.","slide":175,"shape":"15","bookPage":"30"},{"text":"The megacity of Tokyo lots of restaurants. Is the sentence correct?Correct answer: ✗ — The megacity of Tokyo has lots of restaurants.","slide":175,"shape":"16","bookPage":"30"},{"text":"Write three simple sentences about a city or town you know. Write (S) next to the subject and (V) next to the verb.Possible answer: My town (S) has (V) a park. The streets (S) are (V) quiet. I (S) live (V) near the station.","slide":177,"shape":"13","bookPage":"30"},{"text":"1 There aren’t many traffic jams in my town.","slide":181,"shape":"17","bookPage":"31"},{"text":"2 There is an excellent museum.","slide":181,"shape":"18","bookPage":"31"},{"text":"3 There aren’t people from many different countries.","slide":181,"shape":"19","bookPage":"31"},{"text":"4 There are a lot of apartments in the centre.","slide":181,"shape":"20","bookPage":"31"},{"text":"5 There is a beach.","slide":181,"shape":"6","bookPage":"31"},{"text":"6 There aren’t many jobs.","slide":181,"shape":"7","bookPage":"31"},{"text":"Many restaurants are not in my town.Correct answer: There aren’t many restaurants in my town.","slide":184,"shape":"19","bookPage":"31"},{"text":"A famous museum is in my city.Correct answer: There is a famous museum in my city.","slide":184,"shape":"20","bookPage":"31"},{"text":"A lake is not in my town.Correct answer: There isn’t a lake in my town.","slide":185,"shape":"19","bookPage":"31"},{"text":"A lot of cars are in my city.Correct answer: There are a lot of cars in my city.","slide":185,"shape":"20","bookPage":"31"},{"text":"Many expensive shops are in my city.Correct answer: There are many expensive shops in my city.","slide":186,"shape":"13","bookPage":"31"},{"text":"A few big hotels are in my town.Correct answer: There are a few big hotels in my town.","slide":186,"shape":"14","bookPage":"31"},{"text":"Many people are not in my town.Correct answer: There aren’t many people in my town.","slide":186,"shape":"15","bookPage":"31"},{"text":"Discuss whether the sentences in Exercise 5 are true for you.Possible answer: There isn’t a lake in my town, but there are a few big hotels.","slide":189,"shape":"13","bookPage":"31"},{"text":"Write a sentence about museums in Abu Dhabi using there is/are.Correct answer: There are lots of museums.","slide":192,"shape":"18","bookPage":"32"},{"text":"Write a sentence about universities in Abu Dhabi using there is/are.Correct answer: There are many universities.","slide":192,"shape":"19","bookPage":"32"},{"text":"Write a sentence about ports in Abu Dhabi using there is/are.Correct answer: There are ten ports.","slide":192,"shape":"20","bookPage":"32"},{"text":"Write a sentence about the airport in Abu Dhabi using there is/are.Correct answer: There is one airport.","slide":193,"shape":"12","bookPage":"32"},{"text":"Write a sentence about five-star hotels in Abu Dhabi using there is/are.Correct answer: There are many five-star hotels.","slide":193,"shape":"13","bookPage":"32"},{"text":"Write a sentence about the palace in Abu Dhabi using there is/are.Correct answer: There is a palace.","slide":193,"shape":"14","bookPage":"32"},{"text":"I live in Montreal. It is a city in Canada. It is a beautiful city. There are many shops and restaurants. The people are friendly.","slide":195,"shape":"7","bookPage":"33"},{"text":"There is an art festival in June. People in Montreal speak both French and English. It is very crowded with tourists in the summer.","slide":195,"shape":"10","bookPage":"33"},{"text":"In the winter, people like to ice-skate, cross-country ski and play ice hockey.","slide":195,"shape":"13","bookPage":"33"},{"text":"There is a small lake in my town.","slide":199,"shape":"6","bookPage":null},{"text":"There are many local cafes.","slide":199,"shape":"10","bookPage":null},{"text":"There are two cafes in my street. One of the cafes has a large window. From that window, people can see the river.","slide":200,"shape":"6","bookPage":null},{"text":"There is a library in this neighbourhood. A wide path leads to its entrance. There are benches beside the path. People can visit the building or sit outside for a rest.","slide":201,"shape":"7","bookPage":null}];
